begin;
do $$begin if current_database()<>'factory_lean_quality_local' or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port() not in (55490,55491) then raise exception 'Disposable localhost only';end if;end$$;
truncate late_test.checks;
do $$declare x jsonb;f uuid;h private.manufactured_outputs;r jsonb;groups jsonb;g uuid;finished uuid;decision jsonb;item uuid;mr uuid;lot uuid;p jsonb;rev integer;child private.manufactured_outputs;k uuid:=gen_random_uuid();begin
 select a.x into x from output2_test.fixture a;f:=(x->>'factory')::uuid;perform set_config('request.jwt.claim.sub',x->>'owner',false);
 p:=output2_test.payload(x,90,10);g:=gen_random_uuid();finished:=gen_random_uuid();
 p:=jsonb_set(p,'{output_groups}',jsonb_build_array(jsonb_build_object('id',finished,'quantity','90','missing_operations','[]'::jsonb),jsonb_build_object('id',g,'quantity','10','missing_operations',jsonb_build_array(x->>'step1'))));
 r:=public.record_manufactured_output(f,p,gen_random_uuid());select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 select jsonb_agg(value||jsonb_build_object('released',value->>'quantity')) into groups from jsonb_array_elements(h.recorded_groups);
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','0','reason','Accepted original 90 and 10'),1,gen_random_uuid());
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',finished,'quantity','90','location','Finished bay','physical_confirmation',true),2,gen_random_uuid());
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',g,'quantity','10','location','Recovery bay','physical_confirmation',true),3,gen_random_uuid());
 perform public.finish_product_item(f,(x->>'item')::uuid);
 perform public.manufactured_completion_read(f);
 perform late_test.ok(private.output_demand_received(f,h.item_id)=90,'100 order 90 received remains ten short');
 p:=jsonb_build_object('group_id',g,'quantity','10','choice','COMPLETE','operations',jsonb_build_array(x->>'step1'),'reason','Complete original missing printing');
 decision:=public.plan_manufactured_completion(f,h.id,p,4,k);item:=(decision->>'item_id')::uuid;mr:=(decision->>'material_request_id')::uuid;
 perform late_test.ok(public.plan_manufactured_completion(f,h.id,p,4,k)=decision,'decision UUID retries one work item');
 perform late_test.fails(format('select public.plan_manufactured_completion(%L,%L,%L,4,%L)',f,h.id,p,gen_random_uuid()),'output_revision');
 perform public.plan_product_item(f,item,(x->>'line')::uuid,date_trunc('day',clock_timestamp())+interval '4 days 3 hours');
 perform late_test.fails(format('select public.start_product_item(%L,%L)',f,item),'output_material_not_issued');
 select revision into rev from public.material_requests where id=mr;
 perform public.supply_command(f,'material_change',jsonb_build_object('id',mr,'revision',rev,'action','issue','reason','Physical issue for linked work'),gen_random_uuid());
 select lot_id into lot from private.manufactured_completion_work where item_id=item;
 perform late_test.ok((select warehouse_quantity=0 and quantity_available=10 from public.unfinished_lots where id=lot),'issue moves ten to floor without consuming');
 perform public.start_product_item(f,item);x:=x||jsonb_build_object('item',item);
 p:=output2_test.payload(x,4)||jsonb_build_object('input_lot',lot,'input_quantity',4);
 r:=public.record_manufactured_output(f,p,gen_random_uuid());select * into child from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 perform late_test.ok((select quantity_available=6 and warehouse_quantity=0 from public.unfinished_lots where id=lot),'process four preserves unprocessed six');
 perform late_test.ok(private.output_demand_received(f,h.item_id)=90,'recovery recording does not fulfill original demand');
 groups:=jsonb_set(child.recorded_groups,'{0,released}','"4"');
 perform public.manufactured_output_command(f,'QUALITY',child.id,jsonb_build_object('groups',groups,'rejected','0','reason','Recovery inspected'),1,gen_random_uuid());
 perform public.receive_manufactured_output(f,child.id,jsonb_build_object('group_id',groups->0->>'id','quantity','4','location','Finished bay','physical_confirmation',true),2,gen_random_uuid());
 perform late_test.ok(private.output_demand_received(f,h.item_id)=94,'only recovered inspected receipt fulfills four');
 p:=output2_test.payload(x,6)||jsonb_build_object('input_lot',lot,'input_quantity',6);
 r:=public.record_manufactured_output(f,p,gen_random_uuid());select * into child from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 groups:=jsonb_set(child.recorded_groups,'{0,released}','"6"');
 perform public.manufactured_output_command(f,'QUALITY',child.id,jsonb_build_object('groups',groups,'rejected','0','reason','Remaining recovery inspected'),1,gen_random_uuid());
 perform public.receive_manufactured_output(f,child.id,jsonb_build_object('group_id',groups->0->>'id','quantity','6','location','Finished bay','physical_confirmation',true),2,gen_random_uuid());
 perform public.finish_product_item(f,item);
 perform late_test.ok(private.output_demand_received(f,h.item_id)=100 and (select on_hand=100 from public.finished_goods_balances where factory_id=f and product_id=h.product_id),'ninety plus recovered ten fulfills exactly once');
 perform late_test.ok((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=lot),'input ten conserved and fully consumed');
end$$;
set constraints all immediate;
select count(*) assertions from late_test.checks;
rollback;
